function toolbar(role){let opts=['all','Planned','Active','On hold','Completed','In progress','Blocked','Unassessed','Green','Amber','Red','Open','Mitigating','Resolved','Accepted','Pending','Approved','Declined','Deferred','Draft','Submitted','Reviewed','High','Critical','Low','Medium','Cancelled'];return '<div class="po-toolbar"><input type="search" name="query" data-action="search" data-ui-state="true" value="'+esc(st.query)+'" placeholder="Search current page" aria-label="Search visible '+esc(role)+' page">'+btn(icon('plus',16)+'<span class="po-add-label"> Add '+esc(role==='projects'?'project':'record')+'</span>','add:'+role,'po-primary',!can(role))+'</div><div class="po-filter-wrap">'+btn('Filters'+(st.filter!=='all'?' (1)':''),'filters','po-filter',false,'aria-expanded="'+(st.filtersOpen?'true':'false')+'" aria-controls="po-filter-panel"')+(st.filtersOpen?'<div class="po-filter-panel" id="po-filter-panel"><label>Status / priority <select name="filter" data-ui-state="true" data-action="status-filter">'+opts.map(o=>'<option value="'+esc(o)+'" '+(st.filter===o?'selected':'')+'>'+esc(o==='all'?'All':o)+'</option>').join('')+'</select></label></div>':'')+'</div><p class="po-table-caption">Search and filter apply to the current authorized page. Use pagination for older records.</p>';}
