function projectsScreen(){const role=st.projectTab;return header('Project directory','Accountable objectives, phases and owner-assessed status',scope())+warnings(['projects','workstreams'])+'<section class="po-card">'+cardTitle('Company projects & workstreams','<div class="po-switch">'+btn('Projects','project-tab:projects',role==='projects'?'po-primary':'po-secondary')+btn('Workstreams','project-tab:workstreams',role==='workstreams'?'po-primary':'po-secondary')+'</div>')+register(role)+'</section><section class="po-card po-footnote">Project health is set by the accountable owner with a dated rationale. No automated project risk score, portfolio optimization, or sensitive participant records.</section>';}
function timelineScreen(){let rs=page('milestones'),arr=roleInScope('milestones',rs.rows),start=Date.UTC(+st.asOf.slice(0,4),+st.asOf.slice(5,7)-3,1),end=Date.UTC(+st.asOf.slice(0,4),+st.asOf.slice(5,7)+4,1),percent=d=>{if(!iso(d))return null;return Math.max(1,Math.min(99,((Date.parse(d+'T00:00:00Z')-start)/(end-start))*100));};let months=[];for(let i=0;i<7;i++){let d=new Date(Date.UTC(new Date(start).getUTCFullYear(),new Date(start).getUTCMonth()+i,1));months.push(d.toISOString().slice(0,7));}let rows=arr.filter(x=>!st.query||String(x.data.name||'').toLowerCase().includes(st.query.toLowerCase()));let lines=rows.map(x=>{let d=x.data,base=percent(d.baseline_date),cur=percent(d.current_date),actual=percent(d.actual_date),slip=days(d.current_date,d.baseline_date);return '<div class="po-timeline-row"><div class="po-timeline-label"><b>'+esc(d.name)+'</b><small>'+esc(label('projects',d.project_id))+' · '+esc(d.owner||'Unassigned')+'</small><span>'+tag(d.status)+' '+(slip===null?'':slip>0?'<em>+'+slip+' d slip</em>':slip<0?'<em>'+slip+' d earlier</em>':'On baseline')+'</span></div><div class="po-timeline-track"><div class="po-timeline-mid" style="left:'+percent(st.asOf)+'%"></div>'+(base!==null?'<span class="po-tick baseline" style="left:'+base+'%" title="Baseline '+esc(d.baseline_date)+'"></span>':'')+(cur!==null?'<span class="po-tick current" style="left:'+cur+'%" title="Current '+esc(d.current_date)+'"></span>':'')+(actual!==null?'<span class="po-tick actual" style="left:'+actual+'%" title="Actual '+esc(d.actual_date)+'"></span>':'')+'</div>'+btn('Details','detail:milestones:'+x.id,'po-small')+'</div>';}).join('');return header('Milestone timeline','Original baseline, revised target and actual delivery',scope()+btn('New milestone','add:milestones','po-primary',!can('milestones')))+warnings(['milestones','projects','workstreams'])+'<section class="po-card">'+cardTitle('Schedule commitments',btn(st.view==='timeline'?'Table view':'Timeline view','toggle-timeline','po-secondary'))+(st.view==='timeline'?'<div class="po-timeline-scroller" role="region" tabindex="0" aria-label="Seven month milestone timeline"><div class="po-time-grid"><div></div><div class="po-months">'+months.map(x=>'<span>'+esc(x)+'</span>').join('')+'</div></div>'+(lines||'<div class="po-empty">No milestones on this page.</div>')+'</div><div class="po-legend"><span><i class="po-key baseline"></i>Baseline</span><span><i class="po-key current"></i>Current target</span><span><i class="po-key actual"></i>Actual</span><span>Vertical line: reporting date</span></div>':toolbar('milestones')+table('milestones',arr))+pager(rs)+'</section><p class="po-note-row">Timeline dates outside the seven-month window are clipped to the edges; open Details for exact dates. Baseline never changes during a target revision.</p>';}
function deliverableScreen(){let rr=all('deliverables'),items=roleInScope('deliverables',rr.rows),done=metricCoverage(['deliverables','projects','workstreams']);let completed=items.filter(x=>x.data.status==='Completed').length,blocked=items.filter(x=>x.data.status==='Blocked').length;return header('Deliverables','Reviewed outputs, owners and completion evidence',scope())+warnings(['deliverables','projects','workstreams'])+'<div class="po-stat-strip">'+stat('Completed',done?completed:'—','Evidence required')+stat('Blocked',done?blocked:'—','Current status')+stat('Total deliverables',done?items.length:'—','Authorized coverage')+'</div><section class="po-card">'+cardTitle('Delivery register','<span class="po-hint">25 rows per page by default</span>')+register('deliverables')+'</section>';}
function riskScreen(){let role=st.riskTab;let rs=all('risks'),decision=all('decisions'),ok=metricCoverage(['risks','decisions','projects']);let hi=roleInScope('risks',rs.rows).filter(x=>['High','Critical'].includes(x.data.priority)&&!['Resolved','Accepted'].includes(x.data.status)),waiting=roleInScope('decisions',decision.rows).filter(x=>x.data.status==='Pending');return header('Risks & decisions','Escalations, mitigation, and accountable choices',scope())+warnings(['risks','decisions','projects'])+'<div class="po-stat-strip">'+stat('High risks / issues',ok?hi.length:'—','Active owner-assessed priority')+stat('Pending decisions',ok?waiting.length:'—','Awaiting accountable outcome')+'</div><section class="po-card">'+cardTitle('Action register','<div class="po-switch">'+btn('Risks & issues','risk-tab:risks',role==='risks'?'po-primary':'po-secondary')+btn('Decisions','risk-tab:decisions',role==='decisions'?'po-primary':'po-secondary')+'</div>')+register(role)+'</section><p class="po-note-row">Impact and likelihood are manually entered. No patient-level safety or validated pharmacovigilance classification.</p>';}
const researchPrompt='For the saved Project Oversight app, read only authorized projects, workstreams, milestones, deliverables, risks, decisions, and reviewed status updates for the selected reporting cutoff. Verify source coverage, IDs, and owners. Compare current milestone dates to immutable baselines; identify changes, overdue deliverables, active high-priority risks, pending decisions and missing owner updates without inventing green status. Draft a concise leadership narrative with citations to exact authorized record IDs and date. Return Draft report fields only for owner review. If any essential source is unavailable, denied, truncated or lacks the prior snapshot, mark coverage partial and do not imply a complete company-wide report. Do not contact external recipients, auto-approve a report, modify operational records, or create an independent scheduled task.';
function reportScreen(){let role=st.reportTab,report=all('reports'),updates=all('updates'),ok=metricCoverage(['reports','updates','projects','milestones','risks','decisions']),reviewed=roleInScope('updates',updates.rows).filter(x=>x.data.status==='Reviewed'&&iso(x.data.period)&&x.data.period<=st.asOf),rec=reports=>reports.filter(x=>x.data.status==='Approved'&&iso(x.data.period)&&x.data.period<=st.asOf&&iso(x.data.cutoff)&&x.data.cutoff<=st.asOf).sort((a,b)=>String(b.data.period).localeCompare(String(a.data.period)));let a=rec(report.rows),latest=a[0];let dateList=Array.from(new Set(reviewed.map(x=>x.data.period.slice(0,7)))).sort().reverse();let missingPrior=dateList.length<2;return header('Management reports','Project updates and company-wide leadership snapshots',scope()+asOfControl())+warnings(['reports','updates','projects','milestones','risks','decisions'])+'<div class="po-report-grid"><section class="po-report-hero"><span class="po-eyebrow">Leadership briefing</span><h2>From source records to clear decisions.</h2><p>Prepare a factual project briefing with ChatGPT, review the narrative, and save a new report revision.</p>'+btn(st.prompt?'Hide ChatGPT instructions':'Prepare with ChatGPT','toggle-prompt','po-inverse')+(st.prompt?'<div class="po-prompt">'+esc(researchPrompt)+'</div>':'')+'<small>No hidden AI or email run in this view. Manage optional recurring summaries through platform Automations.</small></section><section class="po-card">'+cardTitle('Reporting coverage')+'<div class="po-coverage">'+stat('Reviewed updates',ok?reviewed.length:'—','Dated contributors')+stat('Approved reports',ok?a.length:'—','Company-wide saved revisions')+'</div><div class="po-report-recent"><span>Latest approved company report</span><strong>'+esc(ok&&latest?latest.data.name:'Not available')+'</strong><small>'+esc(ok&&latest?latest.data.period:'Verified source required')+'</small></div>'+(ok&&missingPrior?'<p class="po-warn-note">No comparable prior reporting period. Trend comparison withheld.</p>':'')+'</section></div><section class="po-card">'+cardTitle('Saved reports & contributing updates','<div class="po-switch">'+btn('Reports','report-tab:reports',role==='reports'?'po-primary':'po-secondary')+btn('Status updates','report-tab:updates',role==='updates'?'po-primary':'po-secondary')+'</div>')+register(role)+'</section><p class="po-note-row">Saved reports are authored and reviewed records, not automatically generated at render time. Missing periods are not treated as zero risks.</p>';}
function editorField(role,f,d){let [k,title,kind,required,opts]=f;if(k==='archived')return '';let value=d[k]??'',choices;if(kind.startsWith('relation-')){let rel=kind.slice(9);choices=all(rel).rows.map(x=>[x.id,x.data.name]);}else if(kind==='select')choices=opts.map(x=>[x,x]);let attr=(!can(role,[k])?' disabled ':'')+' name="'+esc(k)+'" data-ui-state="true" data-action="field:'+esc(k)+'" '+(required?'required ':'');let input=choices?'<select'+attr+'><option value="">Choose…</option>'+choices.map(([id,txt])=>'<option value="'+esc(id)+'" '+(String(value)===String(id)?'selected':'')+'>'+esc(txt)+'</option>').join('')+'</select>':kind==='longtext'?'<textarea rows="3"'+attr+'>'+esc(value)+'</textarea>':'<input type="'+(['money','number'].includes(kind)?'number':kind==='date'?'date':'text')+'" '+(['money','number'].includes(kind)?'step="any" ':'')+attr+'value="'+esc(value)+'" />';return '<label class="po-field '+(kind==='longtext'?'wide':'')+'"><span>'+esc(title)+(required?' *':'')+(!can(role,[k])?' (read only)':'')+'</span>'+input+'</label>';}
function editorModal(){let ed=st.editor;if(!ed)return '';return '<div class="po-overlay"><div class="po-drawer" role="dialog" aria-modal="true" aria-label="'+(ed.mode==='edit'?'Edit ':'New ')+esc(ed.role)+' record"><div class="po-drawer-head"><div><h2>'+(ed.mode==='edit'?'Edit':'Add')+' '+esc(ed.role.replace(/s$/,''))+'</h2><p>All required fields stay accessible regardless of column layout.</p></div>'+btn(icon('close',18),'ignore','po-secondary',false,'aria-label="Close editor"')+'</div><form data-action="save-form"><div class="po-drawer-body">'+roles[ed.role].map(f=>editorField(ed.role,f,ed.draft)).join('')+'</div><div class="po-drawer-foot">'+btn('Ignore','ignore','po-secondary')+'<button type="submit" class="po-button po-primary">Review changes</button></div></form></div></div>';}
function deleteModal(){let d=st.del;if(!d)return '';return '<div class="po-overlay"><div class="po-confirm" role="alertdialog" aria-label="Confirm archive"><h2>Archive '+esc(d.name)+'?</h2><p>This preserves record history. Linked active records must first be reassigned or archived; concurrent changes block the proposal.</p><div>'+btn('Cancel','cancel-delete','po-secondary')+btn('Review archive','review-delete','po-primary')+'</div></div></div>';}
function detailModal(){let d=st.details;if(!d)return '';let row=get(d.role,d.id);if(!row)return '';let extra=d.role==='projects'?'<div class="po-drawer-callout">'+btn('Add workstream','prefill:workstreams:'+row.id+':project','po-secondary',!can('workstreams'))+btn('Add milestone','prefill:milestones:'+row.id+':project','po-secondary',!can('milestones'))+'</div>':d.role==='milestones'?'<div class="po-drawer-callout">'+btn('Linked deliverable','prefill:deliverables:'+row.id+':milestone','po-secondary',!can('deliverables'))+'</div>':'';return '<div class="po-overlay"><div class="po-drawer" role="dialog" aria-modal="true" aria-label="Record detail"><div class="po-drawer-head"><div><h2>'+esc(row.data.name)+'</h2><p>Authorized record · version '+row.version+'</p></div>'+btn(icon('close',18),'close-detail','po-secondary',false,'aria-label="Close details"')+'</div><div class="po-detail-body">'+Object.entries(row.data).filter(([k])=>k!=='archived').map(([k,v])=>'<div class="po-detail-row"><span>'+esc(k.replace(/_/g,' '))+'</span><strong>'+esc(format(d.role,k,v))+'</strong></div>').join('')+extra+'</div><div class="po-drawer-foot">'+btn('Close','close-detail','po-secondary')+btn('Edit','edit:'+d.role+':'+row.id,'po-primary',!can(d.role))+'</div></div></div>';}
const views={overview,projects:projectsScreen,timeline:timelineScreen,deliverables:deliverableScreen,risks:riskScreen,reports:reportScreen};
const html='<div class="po-shell"><aside class="po-sidebar"><div class="po-app-title"><span>PROJECT OVERSIGHT</span><strong>Delivery command center</strong></div><nav aria-label="App sections">'+ordered.map(id=>{let x=screens.find(s=>s[0]===id);return btn(icon(id)+'<span>'+esc(x[1])+'</span>','nav:'+id,'po-nav-item '+(st.route===id?'active':''),false,'aria-current="'+(st.route===id?'page':'false')+'"');}).join('')+'</nav><div class="po-sidebar-end"><span class="po-indicator"></span>Internal company workspace<br><small>Access controlled by platform</small></div></aside><main class="po-main"><div class="po-topbar"><span>'+esc(layout.heading||cfg.heading||'Project Oversight')+'</span><div>'+tag('Internal')+btn(icon('settings',18),'tracker:layout','po-settings',false,'aria-label="Layout settings"')+'</div></div><div class="po-content">'+(st.notice?'<div class="po-notice" role="status">'+esc(st.notice)+'</div>':'')+(views[st.route]||overview)()+'</div><footer class="po-footer">Company project coordination · reviewed changes only · internal operational use</footer></main></div>'+editorModal()+deleteModal()+detailModal();
const css=typeof PROJECT_CSS==='string'?PROJECT_CSS:'';
return {html,css,state:st};
